{#- Authfly middle layer for Twig: macros over the UI8Kit 3 primitives (ui/*), classes from Authfly\Twig\Skin.
    Text arguments are escaped here; `children` arguments are trusted HTML built by these macros only. -#}

{#- codegen:begin lucide-icon: Code generated by authfly/codegen from specs/components/lucide-icon.def.ts. DO NOT EDIT. -#}
{%- macro icon(name, size) -%}
{%- set svg -%}<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" width="100%" height="100%" aria-hidden="true" focusable="false">{{ af_lucide(name) }}</svg>{%- endset -%}
{{ include('ui/icon/Icon.html.twig', {size: size ?: 'sm', attrs: {'data-lucide': name}, children: svg}, with_context = false) }}
{%- endmacro -%}
{#- codegen:end lucide-icon -#}

{#- codegen:begin layout-prim: Code generated by authfly/codegen from specs/components/layout.def.ts. DO NOT EDIT. -#}
{%- macro box(tag, class, attrs, children) -%}
{{ include('ui/box/Box.html.twig', {tag: tag ?: '', class: class ?: '', attrs: af_attrs(attrs ?? {}), children: children ?? ''}, with_context = false) }}
{%- endmacro -%}

{%- macro text(tag, class, attrs, children) -%}
{{ include('ui/text/Text.html.twig', {tag: tag ?: '', class: class ?: '', attrs: af_attrs(attrs ?? {}), children: children ?? ''}, with_context = false) }}
{%- endmacro -%}
{#- codegen:end layout-prim -#}

{#- codegen:begin card: Code generated by authfly/codegen from specs/components/card.def.ts. DO NOT EDIT. -#}
{%- macro card(class, attrs, children) -%}
{{ _self.box('section', af_skin('card', class), attrs, children) }}
{%- endmacro -%}
{#- codegen:end card -#}

{#- codegen:begin layout: Code generated by authfly/codegen from specs/components/layout.def.ts. DO NOT EDIT. -#}
{%- macro stack(gap, align, justify, class, attrs, children) -%}
{{ _self.box('', af_cn('flex flex-col', af_gap(gap, '4'), af_align(align, 'stretch'), af_justify(justify), class), attrs, children) }}
{%- endmacro -%}

{%- macro group(gap, align, justify, class, attrs, children) -%}
{{ _self.box('', af_cn('flex min-w-0', af_gap(gap, '2'), af_align(align, 'center'), af_justify(justify), class), attrs, children) }}
{%- endmacro -%}

{#- form: the Form primitive (method post) with the Authfly grid; the form error id is passed to each field. -#}
{%- macro form(action, class, attrs, children) -%}
{{ include('ui/form/Form.html.twig', {action: action, method: 'post', class: af_cn('grid gap-4', class), attrs: af_attrs(attrs ?? {}), children: children}, with_context = false) }}
{%- endmacro -%}
{#- codegen:end layout -#}

{#- codegen:begin field-hidden: Code generated by authfly/codegen from specs/components/field.def.ts. DO NOT EDIT. -#}
{#- hidden: value always emitted, an empty one included (the primitive omits only null). -#}
{%- macro hidden(name, value) -%}
{{ include('ui/input/Input.html.twig', {type: 'hidden', name: name, value: value ?? ''}, with_context = false) }}
{%- endmacro -%}
{#- codegen:end field-hidden -#}

{#- codegen:begin title: Code generated by authfly/codegen from specs/components/title.def.ts. DO NOT EDIT. -#}
{%- macro title(level, id, role, title) -%}
{{ _self.text(level == 1 ? 'h1' : 'h2', af_text(level == 1 ? 'title' : 'subtitle'), {id: id, role: role}, af_esc(title)) }}
{%- endmacro -%}
{#- codegen:end title -#}

{#- codegen:begin alert: Code generated by authfly/codegen from specs/components/alert.def.ts. DO NOT EDIT. -#}
{%- macro alert(tone, icon, id, testid, message) -%}
{%- set c -%}{% if icon %}{{ _self.icon(icon) }}{% endif %}{{ message }}{%- endset -%}
{{ _self.box('', af_skin('alert', tone), {role: tone == 'destructive' ? 'alert' : 'status', 'aria-live': 'polite', 'data-slot': 'alert', id: id, 'data-testid': testid}, c) }}
{%- endmacro -%}
{#- codegen:end alert -#}

{#- codegen:begin badge: Code generated by authfly/codegen from specs/components/badge.def.ts. DO NOT EDIT. -#}
{%- macro badge(variant, testid, label) -%}
{{ _self.text('span', af_skin('badge', variant ?: 'default'), {'data-slot': 'badge', 'data-testid': testid}, af_esc(label)) }}
{%- endmacro -%}

{%- macro icon_badge(icon, tone) -%}
{{ _self.text('span', af_skin('iconBadge', tone ?: 'default'), {'data-slot': 'icon-badge'}, _self.icon(icon, 'lg')) }}
{%- endmacro -%}
{#- codegen:end badge -#}

{#- codegen:begin field: Code generated by authfly/codegen from specs/components/field.def.ts. DO NOT EDIT. -#}
{#- field: label + Input + hint + error. f = {label, for, hint, error, formError, input: Input props, describe: own ids,
    suffix: trusted html placed after the input in a Group}. aria-describedby = own + hint + error + form error;
    aria-invalid="true" when the field or the form shows an error. -#}
{%- macro field(f) -%}
{%- set hintId = f.hint ?? '' ? f.for ~ '-hint' : null -%}
{%- set errId = f.error ?? '' ? f.for ~ '-error' : null -%}
{%- set wired = (f.input|default({}))|merge({id: f.for, class: af_skin('input'), ariaDescribedBy: af_describe(f.describe ?? null, hintId, errId, f.formError ?? null), ariaInvalid: ((f.error ?? '') or (f.formError ?? '')) ? 'true' : null, attrs: af_attrs((f.input.attrs ?? {})|merge({'data-testid': 'field'}))}) -%}
{%- set ctl -%}{{ include('ui/input/Input.html.twig', wired, with_context = false) }}{%- endset -%}
{%- if f.suffix ?? '' -%}{%- set ctl = _self.group('2', '', '', '', {}, ctl ~ f.suffix) -%}{%- endif -%}
{%- set lbl -%}{{ include('ui/label/Label.html.twig', {htmlFor: f.for, class: af_skin('label'), children: af_esc(f.label)}, with_context = false) }}{%- endset -%}
{%- set c -%}
{{ lbl }}{{ ctl }}
{%- if hintId %}{{ _self.text('', af_text('hint'), {id: hintId}, af_esc(f.hint)) }}{% endif -%}
{%- if errId %}{{ _self.text('', 'text-xs font-semibold text-destructive', {id: errId}, af_esc(f.error)) }}{% endif -%}
{%- endset -%}
{{ _self.box('', 'flex min-w-0 flex-col gap-2', {}, c) }}
{%- endmacro -%}
{#- codegen:end field -#}

{#- codegen:begin parts: Code generated by authfly/codegen from specs/components/parts.def.ts. DO NOT EDIT. -#}
{%- macro head(id, title, lead, align, role, extra) -%}
{%- set c -%}{{ _self.title(1, id ~ '-title', null, title) }}{{ _self.text('', af_text('muted'), {}, af_esc(lead)) }}{{ extra ?? '' }}{%- endset -%}
{{ _self.stack('2', align ?: 'start', '', '', {role: role}, c) }}
{%- endmacro -%}

{%- macro messages(id, error, info) -%}
{%- if error %}{{ _self.alert('destructive', 'circle-alert', id ~ '-error', 'authfly-error', af_esc(error)) }}{% endif -%}
{%- if info %}{{ _self.alert('default', 'info', '', 'authfly-info', af_esc(info)) }}{% endif -%}
{%- endmacro -%}

{%- macro link(href, class, testid, label) -%}
{{ include('ui/link/Link.html.twig', {href: href, class: class, attrs: af_attrs({'data-testid': testid}), children: af_esc(label)}, with_context = false) }}
{%- endmacro -%}

{%- macro button(href, type, class, attrs, children) -%}
{{ include('ui/button/Button.html.twig', {href: href ?: '', type: type ?: '', class: class, attrs: af_attrs(attrs ?? {}), children: children}, with_context = false) }}
{%- endmacro -%}
{#- codegen:end parts -#}
